{
  "id": "V059",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "지역별 생활 장면에 맞는 광고 이미지 초안 준비 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "배경을 달리한 이미지 후보 생성 및 담당자 검토가 보존됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "생활용품 제품과 광고 이미지 후보가 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "승인된 제품 사진을 입력으로 사용함."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "검토용 광고 이미지 후보가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "제품 외형·브랜드 표현 유지, 성능 변경 및 새 효능 문구 추가 금지, 승인 후 게시가 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능 추가가 보이지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "광고 담당자가 후보를 검토하고 게시가 승인 뒤 진행된다는 역할 구분이 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "후보 검토는 담당자의 역할이며, 실제 게시는 승인 뒤 진행됨. AI가 게시하거나 승인한다고 주장하지 않음."
}
